UPDATE companies SET description='The company has operated as a custom plastics injection molder for over four decades, building a reputation for performance and quality in the plastics manufacturing industry.

The company specializes in custom injection molding of plastics components and assemblies, with a core capability in two-shot injection molding—a process that injects two different materials sequentially in a single mold cycle. In 2026, the company plans to expand its facility infrastructure, add two-shot molding capacity, and install two pad printing lines and corona surface treatment equipment for specialized decorative processes.

The company emphasizes performance, combining technical expertise, advanced equipment, and project management to meet customer expectations on time. Its quality policy stresses continuous improvement, competitive pricing, and prompt service, backed by ISO 9001:2015 registration and UL certification for fabricated parts.', certifications=ARRAY['ISO 9001:2015','UL QMMY2.E104015']::text[], profile='{"capabilities": ["Two-shot injection molding", "Custom plastics injection molding", "Pad printing", "Corona surface treatment", "Technical services", "Project management"], "industries": [], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Two-shot injection molding in a single manufacturing step", "Technical services group with state-of-the-art equipment", "Professional project management ensuring on-time delivery", "ISO 9001:2015 registered quality system", "UL certified for fabricated parts (QMMY2.E104015)"], "facts_used": ["Founded 1981 -> db", "Headquarters Searcy, Arkansas -> db", "Two-shot injection molding capability -> /", "ISO 9001:2015 certified -> /quality", "UL certified QMMY2.E104015 -> /quality", "Plans for 2026 facility expansion and pad printing lines -> /", "Quality policy: continuous improvement, competitive pricing, prompt service -> /quality", "Technical services group, state-of-the-art equipment, professional project management -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Premier Technical Plastics apart from other custom plastics injection molders", "founded_year": "1981", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='premier-technical-plastics' AND approved AND profile IS NULL;
UPDATE companies SET description='Premium Auto Parts has operated from Salt Lake City, Utah since 2005, serving the greater Salt Lake City area as a used auto parts dealer.

The company stocks used parts for all makes and models ranging from compact cars to light-duty trucks. Its inventory is organized with downloadable cut sheets covering vehicle configurations such as two- and four-door unibodies, full-frame sedans, SUVs, minivans, full-size vans, and various truck cab styles. Fulfillment options include nationwide shipping, daily local deliveries, and regional courier services. A warranty of up to 90 days applies to most recycled parts, depending on the component type, and the sales team includes members with over 40 years of automotive parts experience.

The business supports both walk-in and remote orders through an online search tool and phone assistance.

