UPDATE companies SET description='R. Stahl Inc. was founded in 1979 and is headquartered in Houston, Texas. The company employs over 1,000 people and operates as a manufacturer of explosion-protected electrical and electronic products for hazardous and harsh industrial environments.

The company produces a broad range of switchgear and control equipment, including lockable load switchgear, motor switchgear, and control cabinets made from glass-fiber reinforced polyester. Its portfolio extends to control stations, circuit breaker assemblies, disconnect and transfer switches, plugs and receptacles, empty enclosures for hazardous and harsh areas, intrinsically safe isolators and barriers, remote I/O systems, terminal junction boxes, HMIs, and power distribution systems. These products are designed using protection methods such as intrinsic safety, explosion proof, encapsulation, non incendive, and purge and pressurization, and are rated for NEC Class I, II, Division 1 and 2 as well as CEC Zone classifications.

R. Stahl serves customers in the food and beverage, electronics, chemical, and pharmaceutical industries, along with other industrial facilities that require corrosion-resistant, IP65-rated equipment capable of operating from -20°C to +40°C at up to 690 VAC.

The company emphasizes its specialization in extreme environments, offering products with wide temperature ranges, corrosion-resistant materials, and extreme durability. Its core program highlights round-the-clock orderability, attractive pricing, fast delivery, and versatility as key differentiators.', certifications=ARRAY['ISO 9001','ISO 14001']::text[], profile='{"capabilities": ["Intrinsic safety", "Explosion proof", "Encapsulation", "Non incendive", "Purge and pressurization", "Control stations", "Circuit breaker assemblies", "Disconnect and transfer switches", "Plugs and receptacles", "Empty enclosures (hazardous)", "Empty enclosures (harsh)", "Intrinsically safe isolators and barriers", "Remote IO IS1+", "Terminal junction boxes", "HMIs", "Power distribution systems", "System solutions", "Lockable load switchgear", "Motor switchgear", "Control cabinets"], "industries": ["Food & Beverage", "Electronics", "Chemical", "Pharmaceutical"], "materials": ["Glass-fiber reinforced polyester"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Orderable around the clock", "Attractive prices", "Fast delivery", "Versatile product range", "Explosion-protected equipment for extreme environments"], "facts_used": ["founded_year -> db", "employee_count -> db", "hq_city -> db", "hq_state_label -> db", "certifications -> db", "products -> db", "industries_served -> db", "description -> db", "product range and protection methods -> /", "core program advantages -> /", "industries served -> /", "materials -> description"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "R. STAHL''s innovative designs have made us the leading manufacturer of explosion-protected electrical and electronic products.", "founded_year": "1979", "employee_count": "1000+", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='r-stahl-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='RCD Components was founded in 1973 in Manchester, New Hampshire, where it remains headquartered. The company was acquired by Gowanda Components Group in 2019 and became part of the iNRCORE Group in 2020, expanding its portfolio within a broader passive-components manufacturer network.

The company designs, manufactures, and tests precision mission-critical resistors — including wirewound, high-surge, carbon-composition, and custom configurations — as well as inductor products. RCD operates a U.S.-based production facility that added a new laboratory and expanded capacity in 2026, supporting high-volume standard and custom orders with an extensive datasheet library for every listed part.

RCD serves space, aerospace, defense, medical, and industrial markets, supplying engineers and procurement teams at organizations where component failure is not an option. Its resistors are used in satellites, launch systems, radar, communications, missile systems, medical equipment, and industrial automation.

RCD differentiates itself by focusing exclusively on resistors, providing direct access to design engineers, and maintaining a zero-defect culture backed by ISO 9001 certification and ITAR compliance. The company advertises lead times up to three times shorter than competing high-reliability resistor manufacturers, with a SWIFT delivery service that can ship components in as little as three days.', certifications=ARRAY['ISO 9001','ITAR']::text[], profile='{"capabilities": ["Resistor design and manufacturing", "Custom resistor development", "Subcontract manufacturing services", "Assembly services", "Testing and qualification", "SWIFT rapid delivery service", "High-surge resistor production", "Wirewound resistor manufacturing", "Carbon composition resistor manufacturing", "Inductor product manufacturing"], "industries": ["Space", "Aerospace", "Defense", "Medical", "Industrial"], "materials": [], "equipment": [], "volume": "", "lead_time": "As little as 3 days via SWIFT delivery service", "tolerances": "", "built_on": ["Resistors are the sole product focus, with direct engineering support", "U.S.-based manufacturing delivering lead times up to 3x shorter than competitors", "ISO 9001 certified and ITAR compliant quality system", "SWIFT delivery service providing components in as little as three days", "Zero-defect manufacturing culture with lean innovation"], "facts_used": ["Founded 1973 in Manchester, NH -> / (homepage timeline)", "Acquired by Gowanda Components Group 2019 -> / (homepage timeline)", "Joins iNRCORE Group 2020 -> / (homepage timeline)", "ISO 9001 certified -> / (homepage) and db", "ITAR compliant -> / (homepage)", "Resistors sole focus -> / (homepage)", "Lead times up to 3x shorter -> / (homepage)", "SWIFT delivery in as little as 3 days -> / (homepage) and db", "Industries: Space, Aerospace, Defense, Medical, Industrial -> / (homepage)", "High-volume production capabilities -> /about-us", "Zero-defect culture -> /about-us", "Custom products specialty ->